class MinCostMaxFlow:
    def __init__(self, n):
        self.Nodes = n
        self.cost = [math.inf] * n
        self.flow = [0] * n
        self.p = [0] * n
        self.edges = []
        self.tot_cost = 0
        self.tot_flow = 0

    def add_edge(self, from_node, to_node, cost, flow):
        self.edges.append((from_node, to_node, cost, flow))
        self.edges.append((to_node, from_node, -cost, 0))

    def get_path(self, src, sink):
        self.clear(self.Nodes)
        self.flow[src] = math.inf
        self.cost[src] = 0
        for _ in range(self.Nodes):
            for i in range(len(self.edges)):
                if self.edges[i][3] > 0 and self.cost[self.edges[i][1]] > self.cost[self.edges[i][0]] + self.edges[i][2]:
                    self.cost[self.edges[i][1]] = self.cost[self.edges[i][0]] + self.edges[i][2]
                    self.flow[self.edges[i][1]] = min(self.flow[self.edges[i][0]], self.edges[i][3])
                    self.p[self.edges[i][1]] = i

    def cost_flow(self, src, sink):
        if src == sink:
            self.tot_cost = 0
            self.tot_flow = math.inf
        self.tot_cost = 0
        self.tot_flow = 0
        while True:
            self.get_path(src, sink)
            if self.flow[sink] == 0:
                break
            for cur in range(sink, src, -1):
                rI = self.p[cur] % 2 + 1 if self.p[cur] % 2 == 0 else self.p[cur] - 1
                self.edges[self.p[cur]][3] -= self.flow[sink]
                self.edges[rI][3] += self.flow[sink]
                self.tot_cost += self.edges[self.p[cur]][2] * self.flow[sink]
            self.tot_flow += self.flow[sink]

    def clear(self, n):
        self.Nodes = n
        self.cost = [math.inf] * n
        self.flow = [0] * n
        self.p = [0] * n

    def get_flow(self):
        return self.tot_flow

    def get_cost(self):
        return self.tot_cost

def get(v, vv):
    for i in range(len(v)):
        for j in range(len(v[i])):
            if v[i][j] != '0' and v[i][j].isdigit():
                ini(i, j, v, vv)

def ini(x, y, v, vv):
    v[x][y] = 0
    q = [(x * len(v) + y, 0)]
    while q:
        x, y = divmod(q[0][0], len(v))
        q.pop(0)
        for i in range(4):
            nx, ny = x + dx[i], y + dy[i]
            if nx < 0 or nx >= len(v) or ny < 0 or ny >= len(v) or v[nx][ny] != -1 or v[nx][ny] == 'Y':
                continue
            if v[nx][ny] == '0' and (v[x][y] + 1 <= vv[nx][ny] or vv[nx][ny] == -1):
                v[nx][ny] = v[x][y] + 1
                if v[nx][ny] != vv[nx][ny]:
