            elif vv[nx][ny] == -1 or vv[nx][ny] > v[x][y] + 1:
                v[nx][ny] = v[x][y] + 1
                q.append((nx * len(v) + ny, v[nx][ny]))

def add_edge(i, j, x, y, mcf):
